const https = require('https');

const connectionString = "postgresql://neondb_owner:npg_NafhUtWPF51V@ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech/neondb?sslmode=require";

async function fetchInvoiceData() {
  return new Promise((resolve, reject) => {
    try {
      // Accept either invoice_id (INV...) or vendor_id (VEND...) from input
      const rawInput = typeof $vendor_id !== 'undefined' ? String($vendor_id) : '';

      const invoiceMatch = rawInput.match(/INV\w+/i);
      const vendorMatch = rawInput.match(/VEND\d+/i);

      let query, params, lookupMode;

      if (invoiceMatch) {
        // Single invoice lookup - full JOIN to get all data needed by all 3 agents
        lookupMode = 'invoice';
        query = `
          SELECT
            i.invoice_id,
            i.date            AS invoice_date,
            i.vendor_id,
            i.invoice_number,
            i.po_id,
            i.grn_id,
            i.invoice_amount,
            i.gstin            AS invoice_gstin,
            po.po_amount,
            po.status          AS approval_status,
            po.po_date,
            po.vendor_id       AS po_vendor_id,
            gr.received_amount AS grn_amount,
            gr.receipt_date,
            vm.vendor_name,
            vm.official_gstin  AS official_gstin,
            vm.risk_rating     AS vendor_risk_rating,
            vm.blacklist_status
          FROM invoices i
          LEFT JOIN purchase_orders po  ON i.po_id  = po.po_id
          LEFT JOIN goods_receipts  gr  ON i.grn_id = gr.grn_id
          LEFT JOIN vendor_master   vm  ON i.vendor_id = vm.vendor_id
          WHERE i.invoice_id ILIKE $1
          LIMIT 1;
        `;
        params = [invoiceMatch[0].toUpperCase()];
      } else if (vendorMatch) {
        // Vendor-level lookup - get all invoices for this vendor
        lookupMode = 'vendor';
        query = `
          SELECT
            i.invoice_id,
            i.date            AS invoice_date,
            i.vendor_id,
            i.invoice_number,
            i.po_id,
            i.grn_id,
            i.invoice_amount,
            i.gstin            AS invoice_gstin,
            po.po_amount,
            po.status          AS approval_status,
            po.po_date,
            gr.received_amount AS grn_amount,
            gr.receipt_date,
            vm.vendor_name,
            vm.official_gstin  AS official_gstin,
            vm.risk_rating     AS vendor_risk_rating,
            vm.blacklist_status
          FROM invoices i
          LEFT JOIN purchase_orders po  ON i.po_id  = po.po_id
          LEFT JOIN goods_receipts  gr  ON i.grn_id = gr.grn_id
          LEFT JOIN vendor_master   vm  ON i.vendor_id = vm.vendor_id
          WHERE i.vendor_id ILIKE $1
          ORDER BY i.date DESC
          LIMIT 20;
        `;
        params = [vendorMatch[0].toUpperCase()];
      } else {
        return resolve(JSON.stringify({
          error: "Invalid input",
          details: "Please provide an invoice ID (e.g., INV40001) or vendor ID (e.g., VEND1001).",
          raw_input: rawInput
        }, null, 2));
      }

      const postData = JSON.stringify({ query, params });
      const options = {
        hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',
        port: 443,
        path: '/sql',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Neon-Connection-String': connectionString,
          'Content-Length': Buffer.byteLength(postData)
        }
      };

      const req = https.request(options, (res) => {
        let body = '';
        res.on('data', chunk => body += chunk);
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            try {
              const parsed = JSON.parse(body);
              const rows = parsed.rows || parsed;

              if (!rows || rows.length === 0) {
                return resolve(JSON.stringify({
                  error: `No records found`,
                  lookup_mode: lookupMode,
                  lookup_value: params[0]
                }, null, 2));
              }

              // For single invoice, return the row directly with extra context
              if (lookupMode === 'invoice') {
                const row = rows[0];
                // Add mismatch helpers for Phase 2A
                const inv = parseFloat(row.invoice_amount) || 0;
                const po  = parseFloat(row.po_amount) || 0;
                const grn = parseFloat(row.grn_amount) || 0;
                row._three_way_match_ok = (inv > 0 && po > 0 && grn > 0)
                  ? (Math.abs(inv - po) / po < 0.01 && Math.abs(inv - grn) / grn < 0.01)
                  : null;
                row._requires_enhanced_approval = inv > 100000;
                resolve(JSON.stringify(row, null, 2));
              } else {
                // For vendor, return all invoices as array
                resolve(JSON.stringify({ vendor_id: params[0], invoice_count: rows.length, invoices: rows }, null, 2));
              }
            } catch (e) {
              resolve(JSON.stringify({ error: "JSON parse failed", details: e.message }));
            }
          } else {
            resolve(JSON.stringify({ error: `Neon HTTP Error ${res.statusCode}`, details: body }));
          }
        });
      });

      req.on('error', e => resolve(JSON.stringify({ error: "Network error", message: e.message })));
      req.write(postData);
      req.end();

    } catch (err) {
      resolve(JSON.stringify({ error: String(err), message: err.message }));
    }
  });
}

return await fetchInvoiceData();

try {
    const parseFlags = (str) => {
        try {
            const match = String(str).match(/\[.*\]/s);
            if (match) return JSON.parse(match[0]);
            return [];
        } catch(e) { return []; }
    };

    let allFlags = [
        ...parseFlags($flags_2a),
        ...parseFlags($flags_2b),
        ...parseFlags($flags_2c)
    ];

    let highestSeverity = "NONE";
    const severityRankParams = {"CRITICAL":4, "HIGH":3, "MEDIUM":2, "LOW":1, "NONE":0 };

    allFlags.forEach(f => {
        let s = String(f.Severity || f.severity || "LOW").toUpperCase();
        if (severityRankParams[s] > severityRankParams[highestSeverity]) {
            highestSeverity = s;
        }
    });

    let polVers = typeof $policy_version === "string" ? parseFloat($policy_version.replace(/[^0-9.]/g, '')) : 1.0;

    let result = {
        risk_rating: highestSeverity,
        flags_detected: allFlags,
        policy_version_applied: isNaN(polVers) ? 1.0 : polVers
    };

    return JSON.stringify(result);
} catch(err) {
    return JSON.stringify({ risk_rating: "ERROR", flags_detected: [], policy_version_applied: 1.0 });
}

