async function fetchPolicy() {
  return new Promise((resolve) => {
    const postData = JSON.stringify({
      query: "SELECT policy_id, markdown_content, version_number FROM company_policies WHERE is_active = true ORDER BY version_number DESC LIMIT 1;"
    });

    const options = {
      hostname: 'ep-bitter-credit-a1ffz9vw.ap-southeast-1.aws.neon.tech',
      port: 443, path: '/sql', method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Neon-Connection-String': connectionString,
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', c => body += c);
      res.on('end', () => {
        try {
          const parsed = JSON.parse(body);
          const rows = parsed.rows || parsed;
          if (rows && rows.length > 0) {
            const policy = rows[0];
            // Return both markdown and version as a combined JSON
            resolve(JSON.stringify({
              policy_markdown: policy.markdown_content,
              policy_version: policy.version_number,
              policy_id: policy.policy_id
            }, null, 2));
          } else {
            resolve(JSON.stringify({ policy_markdown: "No active policy found.", policy_version: "N/A" }));
          }
        } catch(e) {
          resolve(JSON.stringify({ policy_markdown: "Policy fetch failed: " + e.message, policy_version: "N/A" }));
        }
      });
    });

    req.on('error', e => resolve(JSON.stringify({ policy_markdown: "Network error: " + e.message, policy_version: "N/A" })));
    req.write(postData);
    req.end();
  });
}

const result = JSON.parse(await fetchPolicy());
// Store both keys separately so agents can use them as flow state variables
return JSON.stringify(result);
